function useShouldReduceMotion() {
  const reducedMotion = useReducedMotionSetting();
  const prefersReduced = React.useSyncExternalStore(
    subscribeToReducedMotion,
    () => window.matchMedia(REDUCED_MOTION_QUERY).matches,
